--
-- Disparadores `detalle_transacciones`
--
DELIMITER $$
CREATE TRIGGER `trg_actualizar_stock_transaccion` AFTER INSERT ON `detalle_transacciones` FOR EACH ROW BEGIN
    DECLARE v_tipo_nombre VARCHAR(50);
    DECLARE v_stock_anterior INT;

    -- Obtener nombre del tipo de transacción desde la tabla tipos_transaccion
    SELECT tt.nombre INTO v_tipo_nombre 
    FROM transacciones t
    INNER JOIN tipos_transaccion tt ON t.tipo_transaccion_id = tt.id
    WHERE t.id = NEW.transaccion_id;

    SELECT stock_actual INTO v_stock_anterior 
    FROM productos 
    WHERE id = NEW.producto_id;

    IF v_tipo_nombre = 'COMPRA' THEN
        UPDATE productos 
        SET stock_actual = stock_actual + NEW.cantidad
        WHERE id = NEW.producto_id;

            producto_id, tipo_movimiento, cantidad,
            stock_anterior, stock_nuevo, motivo,
            referencia_id, referencia_tipo, usuario_id
        )
        SELECT 
            NEW.producto_id, 'ENTRADA', NEW.cantidad,
            v_stock_anterior, v_stock_anterior + NEW.cantidad,
            CONCAT('Compra - Transacción #', t.numero_transaccion),
            t.id, 'TRANSACCION', t.usuario_id
        FROM transacciones t WHERE t.id = NEW.transaccion_id;

    ELSEIF v_tipo_nombre = 'VENTA' THEN
        UPDATE productos 
        SET stock_actual = stock_actual - NEW.cantidad
        WHERE id = NEW.producto_id;

            producto_id, tipo_movimiento, cantidad,
            stock_anterior, stock_nuevo, motivo,
            referencia_id, referencia_tipo, usuario_id
        )
        SELECT 
            NEW.producto_id, 'SALIDA', NEW.cantidad,
            v_stock_anterior, v_stock_anterior - NEW.cantidad,
            CONCAT('Venta - Transacción #', t.numero_transaccion),
            t.id, 'TRANSACCION', t.usuario_id
        FROM transacciones t WHERE t.id = NEW.transaccion_id;
    END IF;
END
$$
DELIMITER ;

